    Mesh<Point, double> mesh;
    // Collect all vertices from the regular triangulation
    std::map<RT::Vertex_handle, unsigned> vertex_index;
    unsigned idx = 0;
    for (auto vit = rt.finite_vertices_begin(); vit != rt.finite_vertices_end(); ++vit) {
        mesh.vertices.push_back(vit->point().point()); // extract the bare point
        vertex_index[vit] = idx++;
    }

    // Iterate over all finite edges of the regular triangulation.
    // For each edge, gather the incident cells (tetrahedra) that share this edge.
    // The dual of an edge in the power diagram is a polygon (face) whose vertices
    // are the circumcenters of those incident cells. We construct the polygon
    // by collecting those circumcenters, but we store only the indices of the
    // original vertices (the power diagram vertices) in the mesh.
    for (auto eit = rt.finite_edges_begin(); eit != rt.finite_edges_end(); ++eit) {
        // Skip edges that are too short according to the threshold.
        if (!is_small_edge(rt, *eit, threshold))
            continue;

        // Determine the two vertices of the edge.
        RT::Edge edge = *eit;
        RT::Vertex_handle v1 = edge.first->vertex(rt.circumcenter(edge.second, edge.third));
        RT::Vertex_handle v2 = edge.first->vertex(rt.circumcenter(edge.third, edge.second));

        // Collect incident cells (tetrahedra) around the edge.
        std::vector<unsigned> face_vertices;
        RT::Cell_handle cell = edge.first;
        int i = edge.second;
        int j = edge.third;

        // Walk around the edge using circulators.
        RT::Cell_circulator cc_start = rt.incident_cells(edge);
        RT::Cell_circulator cc = cc_start;
        do {
            // For each incident cell, compute its dual point (the power diagram vertex).
            // The dual point is the circumcenter of the cell.
            Point dual_pt = rt.dual(cc);
            // Insert the dual point into the mesh vertices list if not already present.
            // Use a map to avoid duplicates.
            auto it = vertex_index.find(rt.vertex_handle(dual_pt));
            unsigned v_idx;
            if (it == vertex_index.end()) {
                v_idx = mesh.vertices.size();
                mesh.vertices.push_back(dual_pt);
                vertex_index[rt.vertex_handle(dual_pt)] = v_idx;
            } else {
                v_idx = it->second;
            }
            face_vertices.push_back(v_idx);
            ++cc;
        } while (cc != cc_start);

        // Store the polygon (face) with its associated information (edge length).
        double edge_len = std::sqrt(rt.segment(edge).squared_length());
        mesh.push_back(face_vertices, edge_len);
    }

    return mesh;
